"""Actual upstream selection executed in container with networking blocked."""
PROGRAM = 'import sys,json,socket\ndef blocked(*args,**kwargs): raise RuntimeError("Network disabled for selection replay")\nsocket.socket.connect=blocked\nfrom lightrag.utils import TiktokenTokenizer,_truncate_chunks_for_unified_context,generate_reference_list_from_chunks,render_chunks_context_text\ninputs=json.load(sys.stdin);out=[]\nfor row in inputs:\n    tokenizer=TiktokenTokenizer(row[\'tokenizer\'])\n    result={\'case_id\':row[\'case_id\'],\'variants\':{}}\n    for name,chunks in row[\'variants\'].items():\n        selected=_truncate_chunks_for_unified_context(chunks,row[\'limit\'],tokenizer)\n        _,rendered=generate_reference_list_from_chunks(selected)\n        result[\'variants\'][name]={\'selected_ids\':[c[\'chunk_id\'] for c in selected],\'rendered_chunk_tokens\':len(tokenizer.encode(render_chunks_context_text(rendered)))}\n    out.append(result)\nprint(json.dumps(out))\n'
